package sluice_test

import (
	"os"
	"path/filepath"
	"regexp"
	"slices"
	"strconv"
	"strings"
	"testing"
)

// Every figure the README quotes is, to the character, the median of its
// row in docs/benchmarks.md.
//
// This test exists because the two drifted apart within an hour of the
// consolidated file being created. The README was written from one run of
// `consolidate.sh` and the file regenerated by the next, and nothing noticed:
// a README quoting 152 µs beside a table saying 139 µs, both produced by the
// same script on the same machine, neither wrong when it was written.
//
// Numbers in two places is how one of them goes stale. Since the README is
// meant to carry the comparisons — a pointer to a table is not a
// comparison a reader will follow — the duplication stays. The README's
// copies are written by readme-figures.sh from the page, so exact is the
// right comparison, and the fix for a failure is that one command.

// figure is one number the README quotes, between the inline markers
// readme-figures.sh rewrites:
//
//	<!-- figure: BenchmarkWebDBSluiceOneConn -->898 µs<!-- /figure -->
type figure struct {
	benchmark string // the row in docs/benchmarks.md
	readme    string // as written in README.md
}

var figureMarker = regexp.MustCompile(`<!-- figure: (Benchmark\w+) -->([^<]*)<!-- /figure -->`)

// readmeFigures is the one list of quoted numbers both tests below check,
// read from the README's own markers: the hand-kept list it replaces had
// already missed one of the three figures.
func readmeFigures(t *testing.T) []figure {
	t.Helper()
	readme, err := os.ReadFile("README.md")
	if err != nil {
		t.Fatal(err)
	}
	var out []figure
	for _, m := range figureMarker.FindAllStringSubmatch(string(readme), -1) {
		out = append(out, figure{benchmark: m[1], readme: m[2]})
	}
	if len(out) == 0 {
		t.Fatal("README.md holds no <!-- figure: … --> marker; the format changed")
	}
	return out
}

// The tolerance is loose on purpose. The consolidated table reports a median
// with a spread beside it, and the guides round to two or three significant
// figures; what this catches is a figure that came from a different *run*, not
// one rounded differently.
const figureTolerance = 0.06

// showDuration is the README's spelling of a median, the one
// readme-figures.sh writes: ns, µs or ms, whichever keeps the number under
// 1000, to three significant digits.
func showDuration(ns float64) string {
	v, unit := ns, "ns"
	if v >= 999.5 {
		v, unit = v/1000, "µs"
	}
	if v >= 999.5 {
		v, unit = v/1000, "ms"
	}
	switch {
	case v >= 99.95:
		return strconv.FormatFloat(v, 'f', 0, 64) + " " + unit
	case v >= 9.995:
		return strconv.FormatFloat(v, 'f', 1, 64) + " " + unit
	}
	return strconv.FormatFloat(v, 'f', 2, 64) + " " + unit
}

func TestREADMEFiguresMatchTheConsolidatedMeasurements(t *testing.T) {
	consolidated, err := os.ReadFile("docs/benchmarks.md")
	if err != nil {
		t.Skipf("no consolidated measurements: %v", err)
	}
	medians := parseMedians(t, string(consolidated))
	if len(medians) < 10 {
		t.Fatalf("parsed %d medians from the consolidated file; the format changed", len(medians))
	}
	for _, f := range readmeFigures(t) {
		t.Run(f.benchmark, func(t *testing.T) {
			got, ok := medians[f.benchmark]
			if !ok {
				t.Fatalf("%s is not in the consolidated file", f.benchmark)
			}
			if want := showDuration(got); f.readme != want {
				t.Errorf("README says %s, the consolidated median is %.0f ns (%s);\n"+
					"run internal/bench/scripts/readme-figures.sh", f.readme, got, want)
			}
		})
	}
}

func relative(a, b float64) float64 {
	if b == 0 {
		return 1
	}
	d := (a - b) / b
	if d < 0 {
		return -d
	}
	return d
}

var medianRow = regexp.MustCompile(`^\|\s*` + "`" + `(Benchmark\w+)` + "`" + `\s*\|\s*(\d+) ns\s*\|`)

func parseMedians(t *testing.T, doc string) map[string]float64 {
	t.Helper()
	out := map[string]float64{}
	for line := range strings.SplitSeq(doc, "\n") {
		m := medianRow.FindStringSubmatch(line)
		if m == nil {
			continue
		}
		v, err := strconv.ParseFloat(m[2], 64)
		if err != nil {
			t.Fatalf("unparseable median in %q: %v", line, err)
		}
		out[m[1]] = v
	}
	return out
}

// A row whose spread is over the flag threshold must not be quoted in the
// README at all: run-to-run variation larger than the differences being read
// for makes the figure meaningless however carefully it was obtained.
func TestREADMEDoesNotQuoteUnstableRows(t *testing.T) {
	consolidated, err := os.ReadFile("docs/benchmarks.md")
	if err != nil {
		t.Skipf("no consolidated measurements: %v", err)
	}
	flagged := regexp.MustCompile(`^\|\s*` + "`" + `(Benchmark\w+)` + "`" + `.*\*\*\s*\|`)

	var unstable []string
	for line := range strings.SplitSeq(string(consolidated), "\n") {
		if m := flagged.FindStringSubmatch(line); m != nil {
			unstable = append(unstable, m[1])
		}
	}
	if len(unstable) == 0 {
		return
	}
	// Not a failure by itself — the flag is information. It fails only if one
	// of those rows is also a number the README asks a reader to believe —
	// any of them, read from the same markers the test above checks, so the
	// two cannot drift apart.
	quoted := map[string]string{}
	for _, f := range readmeFigures(t) {
		quoted[f.benchmark] = f.readme
	}
	var offenders int
	for _, nm := range unstable {
		if fig, ok := quoted[nm]; ok {
			offenders++
			t.Errorf("%s has a spread over the flag threshold and the README quotes it as %s; "+
				"raise BENCHTIME and regenerate before publishing that number", nm, fig)
		}
	}
	if offenders == 0 {
		t.Logf("%d rows flagged as unstable, none of them quoted: %v", len(unstable), unstable)
	}
}

// duration is a time figure as the documents write it: "47 ns", "3.7 µs",
// "1.11 ms", digits grouped by commas or not.
var duration = regexp.MustCompile(`(\d[\d,]*(?:\.\d+)?) ?(ns|µs|ms)\b`)

// nanos is a duration match in nanoseconds.
func nanos(m []string) float64 {
	v, err := strconv.ParseFloat(strings.ReplaceAll(m[1], ",", ""), 64)
	if err != nil {
		return -1
	}
	return v * map[string]float64{"ns": 1, "µs": 1e3, "ms": 1e6}[m[2]]
}

// sections cuts a Markdown page at its headings: each heading's slug, as
// headingSlugs computes it, holds the text from that heading to the next one
// of the same or a higher level, its subsections included.
func sections(page string) map[string]string {
	type open struct {
		slug  string
		level int
		start int
	}
	lines := strings.Split(page, "\n")
	out := map[string]string{}
	seen := map[string]int{}
	var stack []open
	closeTo := func(level, end int) {
		for len(stack) > 0 && stack[len(stack)-1].level >= level {
			o := stack[len(stack)-1]
			stack = stack[:len(stack)-1]
			out[o.slug] = strings.Join(lines[o.start:end], "\n")
		}
	}
	inFence := false
	for i, line := range lines {
		if strings.HasPrefix(line, "```") {
			inFence = !inFence
			continue
		}
		text := strings.TrimLeft(line, "#")
		level := len(line) - len(text)
		if inFence || level == 0 || !strings.HasPrefix(text, " ") {
			continue
		}
		closeTo(level, i)
		s := slugOf(text)
		if n := seen[s]; n > 0 {
			seen[s] = n + 1
			s = s + "-" + string(rune('0'+n))
		} else {
			seen[s] = 1
		}
		stack = append(stack, open{s, level, i})
	}
	closeTo(1, len(lines))
	return out
}

// measuredIn is every duration a stretch of docs/benchmarks.md states, in
// nanoseconds: written with its unit, or bare in a table column whose header
// names the unit once ("ns per call").
func measuredIn(text string) []float64 {
	var measured []float64
	for _, m := range duration.FindAllStringSubmatch(text, -1) {
		measured = append(measured, nanos(m))
	}
	// The unit is bounded by a space rather than \b, which is ASCII-only and
	// so never matches before "µs".
	unit := regexp.MustCompile(`(?:^|\s)(ns|µs|ms)\b`)
	bare := regexp.MustCompile(`^\s*(\d[\d,]*(?:\.\d+)?)\s*$`)
	var header []string
	lines := strings.Split(text, "\n")
	for i, line := range lines {
		if !strings.HasPrefix(line, "|") {
			header = nil
			continue
		}
		cells := strings.Split(strings.Trim(line, "|"), "|")
		if i+1 < len(lines) && strings.HasPrefix(lines[i+1], "|---") {
			header = cells
			continue
		}
		for c, cell := range cells {
			if c >= len(header) {
				break
			}
			u, n := unit.FindStringSubmatch(header[c]), bare.FindStringSubmatch(cell)
			if u != nil && n != nil {
				measured = append(measured, nanos([]string{"", n[1], u[1]}))
			}
		}
	}
	return measured
}

// paragraphs cuts the prose of a Markdown document into the stretches a link
// is read with: lines up to a blank one, a quote's bare ">" counting as blank,
// and each list item on its own. Each comes with the number of its first
// line. Code blocks and tables are left out: in a guide they hold settings
// and defaults, not measurements.
func paragraphs(doc string) (starts []int, texts []string) {
	var cur []string
	flush := func() {
		if len(cur) > 0 {
			texts = append(texts, strings.Join(cur, "\n"))
			cur = nil
		}
	}
	item := regexp.MustCompile(`^(?:> ?)*\s*(?:[-*]|\d+\.) `)
	inFence := false
	for i, line := range strings.Split(doc, "\n") {
		bare := strings.Trim(line, "> \t")
		if strings.HasPrefix(bare, "```") {
			inFence = !inFence
			flush()
			continue
		}
		if inFence || bare == "" || strings.HasPrefix(bare, "|") {
			flush()
			continue
		}
		if item.MatchString(line) {
			flush()
		}
		if len(cur) == 0 {
			starts = append(starts, i+1)
		}
		cur = append(cur, line)
	}
	flush()
	return starts, texts
}

// cited is a link from a document into a section of docs/benchmarks.md.
var cited = regexp.MustCompile(`benchmarks\.md#([\w-]+)\)`)

// settings are the durations the documents' prose quotes that are conditions
// or bounds rather than measurements, keyed by file and figure, each with
// what it is. Anything else written in ns, µs or ms needs its section.
var settings = map[string]string{
	"docs/guide/deployments.md 100 ms": "a round-trip time the window arithmetic is worked for, and the delay of the proxy the upload was measured through",
	"docs/guide/experimental.md 80 ms": "the round-trip time of an emulated path profile",
	"docs/guide/limits.md 14 ms":       "2^14 ms, the largest max_ack_delay RFC 9000 allows",
}

// Every duration a guide, the architecture or the README quotes is a
// measurement of the section of docs/benchmarks.md its paragraph links to,
// within the README's tolerance and whatever the unit it is written in. A
// figure quoted from memory, or from a session whose table has since been
// regenerated, has no source; and one that matches some number elsewhere on
// the page is no better, which is why the paragraph names where it was read.
// transferable is what lets a reader use a duration measured on another
// machine: a ratio, or the date the measurement was taken.
var transferable = regexp.MustCompile(`×\d|\b20\d\d-\d\d-\d\d\b`)

func TestGuideFiguresHaveASource(t *testing.T) {
	page, err := os.ReadFile("docs/benchmarks.md")
	if err != nil {
		t.Fatal(err)
	}
	bySection := sections(string(page))
	guides, err := filepath.Glob("docs/guide/*.md")
	if err != nil {
		t.Fatal(err)
	}
	for _, f := range append([]string{"README.md", "docs/design/architecture.md"}, guides...) {
		b, err := os.ReadFile(f) //nolint:gosec // G304: a repository path, not input
		if err != nil {
			t.Fatal(err)
		}
		starts, texts := paragraphs(string(b))
		for p, text := range texts {
			figures := slices.DeleteFunc(duration.FindAllStringSubmatch(text, -1), func(m []string) bool {
				_, ok := settings[f+" "+m[0]]
				return ok
			})
			if len(figures) == 0 {
				continue
			}
			var measured []float64
			links := cited.FindAllStringSubmatch(text, -1)
			for _, l := range links {
				s, ok := bySection[l[1]]
				if !ok {
					t.Errorf("%s:%d: links to #%s, no section of docs/benchmarks.md", f, starts[p], l[1])
				}
				measured = append(measured, measuredIn(s)...)
			}
			if len(links) == 0 {
				t.Errorf("%s:%d: quotes %s and links to no section of docs/benchmarks.md", f, starts[p], figures[0][0])
				continue
			}
			// A duration is this machine's: in the README and a guide it
			// comes with what transfers — a ratio against the ceiling or the
			// same bench's reference — or with the day it was measured.
			if f != "docs/design/architecture.md" && !transferable.MatchString(text) {
				t.Errorf("%s:%d: quotes %s with no ratio (×N) and no date of measurement beside it", f, starts[p], figures[0][0])
			}
			for _, m := range figures {
				v := nanos(m)
				if !slices.ContainsFunc(measured, func(w float64) bool { return relative(v, w) <= figureTolerance }) {
					t.Errorf("%s:%d: %s is in no table or sentence of the section it links to", f, starts[p], m[0])
				}
			}
		}
	}
}

// ratio is a multiple as the documents write it: "×6.9", "×11.9". A space
// after the sign ("× 1200") is arithmetic in a comment, not a measurement.
var ratio = regexp.MustCompile(`×(\d+(?:\.\d+)?)\b`)

// unsourcedRatios are the multiples the documents quote that are not in
// docs/benchmarks.md, keyed by file and figure, each with where it comes
// from instead. Anything else written "×N" needs its row there.
var unsourcedRatios = map[string]string{
	"docs/design/architecture.md ×22":                              "DataFusion's published gain, the reference pushdown is compared with",
	"pushdown/demand.go ×22":                                       "DataFusion's published gain, the reference pushdown is compared with",
	"docs/design/adr/0018-zero-values-and-mandatory-bounds.md ×11": "a test's measurement, not a benchmark: h2rtt_test.go, 0.48 against 5.5 MB/s, quoted beside Config.InitialWindowSize",
}

// Every multiple a design document, a decision record, a guide, the README or
// a godoc of the root module quotes as "×N" is in docs/benchmarks.md —
// written there as a multiple, or in a column whose header says ratio —
// within the figures' tolerance. TestGuideFiguresHaveASource holds the
// durations; a ratio escaped it, and the gateway's gain stayed quoted as ×6.9
// in five places after the table that re-measured it said 11.9.
func TestRatiosHaveASource(t *testing.T) {
	page, err := os.ReadFile("docs/benchmarks.md")
	if err != nil {
		t.Fatal(err)
	}
	var measured []float64
	add := func(s string) {
		if v, err := strconv.ParseFloat(strings.ReplaceAll(s, ",", ""), 64); err == nil {
			measured = append(measured, v)
		}
	}
	for _, m := range regexp.MustCompile(`× ?(\d[\d,]*(?:\.\d+)?)`).FindAllStringSubmatch(string(page), -1) {
		add(m[1])
	}
	var header []string
	lines := strings.Split(string(page), "\n")
	for i, line := range lines {
		if !strings.HasPrefix(line, "|") {
			header = nil
			continue
		}
		cells := strings.Split(strings.Trim(line, "|"), "|")
		if i+1 < len(lines) && strings.HasPrefix(lines[i+1], "|---") {
			header = cells
			continue
		}
		for c, cell := range cells {
			if c < len(header) && strings.Contains(strings.ToLower(header[c]), "ratio") {
				add(strings.TrimSpace(cell))
			}
		}
	}

	files := []string{"README.md"}
	for _, root := range []string{"docs/design", "docs/guide"} {
		err := filepath.WalkDir(root, func(p string, d os.DirEntry, err error) error {
			if err == nil && !d.IsDir() && strings.HasSuffix(p, ".md") {
				files = append(files, p)
			}
			return err
		})
		if err != nil {
			t.Fatal(err)
		}
	}
	err = filepath.WalkDir(".", func(p string, d os.DirEntry, err error) error {
		if err != nil {
			return err
		}
		if d.IsDir() {
			if p == "." {
				return nil
			}
			if strings.HasPrefix(d.Name(), ".") || d.Name() == "testdata" {
				return filepath.SkipDir
			}
			if _, err := os.Stat(filepath.Join(p, "go.mod")); err == nil {
				return filepath.SkipDir // a nested module, outside the promise of the docs
			}
			return nil
		}
		if strings.HasSuffix(p, ".go") && !strings.HasSuffix(p, "_test.go") {
			files = append(files, p)
		}
		return nil
	})
	if err != nil {
		t.Fatal(err)
	}

	for _, f := range files {
		b, err := os.ReadFile(f) //nolint:gosec // G304: a repository path, not input
		if err != nil {
			t.Fatal(err)
		}
		for i, line := range strings.Split(string(b), "\n") {
			for _, m := range ratio.FindAllStringSubmatch(line, -1) {
				if _, ok := unsourcedRatios[f+" "+m[0]]; ok {
					continue
				}
				v, err := strconv.ParseFloat(m[1], 64)
				if err != nil {
					continue
				}
				if !slices.ContainsFunc(measured, func(w float64) bool { return relative(v, w) <= figureTolerance }) {
					t.Errorf("%s:%d: %s is in no multiple or ratio column of docs/benchmarks.md", f, i+1, m[0])
				}
			}
		}
	}
}

// consolidate.sh rewrites only what lies between the markers of a block, and
// the page is edited where it is read. A block the page lost would make the
// next run fail after an hour of measuring, and a block written twice, or
// one left open, would have it overwrite the prose that follows. The list of
// blocks is read from the script, the one place it is written.
func TestBenchmarksPageHoldsEveryConsolidatedBlock(t *testing.T) {
	script, err := os.ReadFile("internal/bench/scripts/consolidate.sh")
	if err != nil {
		t.Fatal(err)
	}
	m := regexp.MustCompile(`(?m)^BLOCKS="([a-z -]+)"$`).FindSubmatch(script)
	if m == nil {
		t.Fatal(`consolidate.sh has no BLOCKS="…" line; the script changed shape`)
	}
	blocks := strings.Fields(string(m[1]))
	page, err := os.ReadFile("docs/benchmarks.md")
	if err != nil {
		t.Fatal(err)
	}

	open := regexp.MustCompile(`^<!-- consolidate: (\S+) -->$`)
	count := map[string]int{}
	inside := ""
	for i, line := range strings.Split(string(page), "\n") {
		if o := open.FindStringSubmatch(line); o != nil {
			if inside != "" {
				t.Errorf("docs/benchmarks.md:%d opens block %q inside %q", i+1, o[1], inside)
			}
			inside = o[1]
			count[o[1]]++
			continue
		}
		if line == "<!-- /consolidate -->" {
			if inside == "" {
				t.Errorf("docs/benchmarks.md:%d closes no block", i+1)
			}
			inside = ""
		}
	}
	if inside != "" {
		t.Errorf("docs/benchmarks.md: block %q is never closed", inside)
	}
	for _, b := range blocks {
		if count[b] != 1 {
			t.Errorf("docs/benchmarks.md holds block %q %d times, not once", b, count[b])
		}
		delete(count, b)
	}
	for b := range count {
		t.Errorf("docs/benchmarks.md holds block %q, which consolidate.sh does not produce", b)
	}
}
